function farthestReach(moves: string): number {
  let allLeft = 0, allRight = 0;
  for (const c of moves) {
    allLeft += c === "R" ? 1 : -1;
    allRight += c === "L" ? -1 : 1;
  }
  return Math.max(Math.abs(allLeft), Math.abs(allRight));
}

