class Solution:
    def farthestReach(self, moves: str) -> int:
        all_left = sum(1 if c == "R" else -1 for c in moves)
        all_right = sum(-1 if c == "L" else 1 for c in moves)
        return max(abs(all_left), abs(all_right))

